-- craftprocessor.lua
-- Executes a crafting plan generated by craft.lua library using direct robot API
-- and inventory data received wirelessly.
package.loaded.robinv = nil
package.loaded.gatenet = nil
package.loaded.craft_executor = nil
local component = require("component")
local sides = require("sides")
local event = require "event"
local executor = require "craft_executor"
local args, options = require("shell").parse(...)
local storageSide = options.side == nil and sides.front or tonumber(options.side)
assert(type(storageSide) == "number" and storageSide >= 0 and storageSide <= 5 and storageSide % 1 == 0, "Invalid storage side.")
local gatenet = require "gatenet".new()
local receipts=require("craft_receipts").new()

local running = true
local busy = false
local listenPort = 5990 -- Or your chosen port
local serviceName = "craftServer"

local function stopProgram() running = false return false end
event.listen("interrupted", stopProgram)


-- Handler for Discovery Queries and Announcements (we only care about queries here)
gatenet:listen(gatenet.INTERNAL_EVENT_NAMES.DISCOVERY_ANNOUNCE, function(senderAddress, port, packet)
    if port ~= listenPort then return end
    -- Check if it's a Discovery Query packet
    if packet.hdr[gatenet.HDR_KEYS.TYP] == gatenet.PACKET_TYPES.DISC_QRY then
        local queryPayload = packet.pld
        print(string.format("\n>>> Received Discovery Query from %s", senderAddress))
        print(string.format(">>> --> Query Payload: %s", queryPayload and require("serialization").serialize(queryPayload) or "None"))

        -- Check if the query is for our service
        if type(queryPayload) == 'table' and queryPayload.service == serviceName then
            print(string.format(">>> --> Query matches '%s'. Sending Announcement response.", serviceName))

            -- Prepare the announcement payload
            local announcePayload = {
                serviceName = serviceName,
                status = busy and "Busy" or "Ready",
                serverAddress = component.modem.address
            }
            -- Send the announcement back *specifically* to the client who queried
            local ok, err = gatenet:sendDiscoveryAnnounce(listenPort, announcePayload, senderAddress)
            if not ok then
                print(">>> --> ERROR sending announcement: " .. tostring(err))
            end
        else
            print(">>> --> Query does not match our service. Ignoring.")
        end
    -- Optional: Could also log incoming DISC_ANN packets from other servers if needed
    -- elseif packet.hdr[gatenet.HDR_KEYS.TYP] == gatenet.PACKET_TYPES.DISC_ANN then
    --   print(string.format("\n>>> Received Discovery Announcement from %s", senderAddress))
    end
end)

-- Handler for actual Connection Requests (after client discovers us and calls connect)
gatenet:listen(gatenet.INTERNAL_EVENT_NAMES.CONNECTION_REQUEST, function(senderAddress, port, requestPacket, acceptor)
    if port ~= listenPort then return end
    print(string.format("\n>>> Received Connection Request from discovered client %s", senderAddress))
    local control=type(requestPacket.pld)=="table" and requestPacket.pld.receiptControl==true
    if busy and not control then
        acceptor(false, {message = "Crafting robot is busy."})
        return
    end
    print(">>> --> Accepting connection...")
    local serverPromise, err = acceptor(true, { message = "Welcome to " .. serviceName .. "!" })
    if serverPromise then
        print(string.format(">>> --> Connection established! CID: %s", serverPromise:getConnectionID()))

        serverPromise
        :next(function(self, packet)
            self:clearTimeout()
            if packet and packet.hdr and packet.hdr[gatenet.HDR_KEYS.TYP] == gatenet.PACKET_TYPES.DATA then
                local receivedData = packet.pld
                if type(receivedData) ~= "table" then
                    self:sendData{status = "FAILED", message = "Invalid request payload."}
                    self:disconnect({reason = "Invalid request"})
                    return
                end
                local command = receivedData.command
                -- if command == nil then print(">>> --> No command in request") return else print(string.format(">>> --> Command: %s", command) end 
                if command then
                    if command == "job_status" then
                        local receipt,why=receipts.lookup(receivedData.jobId,senderAddress)
                        self:sendData(receipt or {status="FAILED",jobId=receivedData.jobId,message=why})
                    elseif command == "craft" then
                        local craftPlan = receivedData.plan
                        if receivedData.jobId then
                            local existing,why=receipts.lookup(receivedData.jobId,senderAddress)
                            if not existing then self:sendData{status="FAILED",jobId=receivedData.jobId,message=why};return end
                            if existing.status~="NOT_FOUND" or receivedData.retryOnly then
                                local admitted,receipt=receipts.begin(receivedData.jobId,senderAddress,craftPlan,true)
                                self:sendData(admitted==nil and {status="FAILED",jobId=receivedData.jobId,message=receipt} or receipt)
                                return
                            end
                        end
                        if busy then
                            self:sendData{status = "FAILED", message = "Crafting robot is busy."}
                            return
                        end
                        local valid, validationError = executor.validatePlan(craftPlan)
                        if not valid then
                            self:sendData{status = "FAILED", message = validationError}
                            return
                        end
                        if control then
                            self:sendData{status="FAILED",jobId=receivedData.jobId,message="Control connections cannot submit new crafting jobs."};return
                        end
                        if receivedData.jobId then
                            local admitted,receipt=receipts.begin(receivedData.jobId,senderAddress,craftPlan)
                            if admitted~=true then
                                self:sendData(admitted==nil and {status="FAILED",jobId=receivedData.jobId,message=receipt} or receipt);return
                            end
                        end
                        busy = true
                        local ok, completed, executionError = xpcall(function()
                            return executor.executePlan(craftPlan, {
                                side = storageSide,
                                shouldContinue = function() return running and self:isActive() end,
                                onProgress = function(message)
                                    self:sendData{status = "WORKING", message = message}
                                end
                            })
                        end, debug.traceback)
                        if not ok then executionError = completed; completed = false end
                        if not completed then
                            local cleanupOk, returned, cleanupError = pcall(executor.dumpInventory, storageSide)
                            if not cleanupOk or not returned then
                                executionError = tostring(executionError) .. "; cleanup failed: " .. tostring(cleanupError or returned)
                            end
                        end
                        local terminal={status = completed and "COMPLETE" or "FAILED", message = executionError}
                        if receivedData.jobId then terminal=receipts.finish(receivedData.jobId,terminal.status,terminal.message) end
                        busy = false
                        self:sendData(terminal)
                    else
                        self:sendData{status = "FAILED", message = "Unknown command: " .. tostring(command)}
                    end
                else
                    print(">>> --> --> Received unexpected data. Closing.")
                    self:disconnect({ reason = "Expected valid command" })
                end
            end
        end)
        :catch(function(self, reason, packet)
            print(string.format(">>> --> Server Connection Error/Closed (CID: %s): %s", self:getConnectionID() or "N/A", tostring(reason)))
        end)
        :finally(function(self, reason)
            print(string.format(">>> --> Server Promise Finalized (CID: %s)", self:getConnectionID() or "N/A"))
        end)
        :timeout(10, function(self)
            self:disconnect({reason = "No crafting request received."})
        end)
    else
        print(">>> --> ERROR Failed to accept connection: " .. tostring(err))
    end
end)

-- Startup and the main loop share one cleanup path.
local ok, startupError = xpcall(function()
if not gatenet:openPort(listenPort) then
  error("Failed to open server port " .. listenPort)
end
if not gatenet:startListener() then
    error("Failed to start Gatenet listener")
end

print("CraftProcessor ready. Awaiting connection.")

while running do os.sleep(0.1) end
end, debug.traceback)
local listenerOk, listenerError = pcall(event.ignore, "interrupted", stopProgram)
local cleanupOk, cleanupError = pcall(gatenet.shutdown, gatenet)
if not ok then error(startupError, 0) end
if not cleanupOk then error(cleanupError, 0) end
if not listenerOk then error(listenerError, 0) end
print("CraftProcessor shutting down.")
